;display:block;margin-top:2px}.priority-label,.regular-label{display:inline-block;padding:3px 8px;border-radius:999px;font-size:11px;font-weight:900;margin-left:6px}.priority-label{background:#fed7aa;color:#9a3412}.regular-label{background:#e5e7eb;color:#374151}.status-badge{display:inline-block;min-width:116px;text-align:center;padding:6px 10px;border-radius:999px;font-size:11px;font-weight:900;text-transform:uppercase}.status-waiting{background:#fef3c7;color:#92400e}.status-called{background:#dbeafe;color:#1e40af}.status-gis{background:#dcfce7;color:#166534}.status-held{background:#fee2e2;color:#991b1b}.counter-chip{display:block;margin-top:4px;color:#0b2e83;font-size:12px;font-weight:900}.action-group{display:flex;gap:6px;justify-content:center;align-items:center}.action-group form{margin:0;display:inline-flex;gap:6px;align-items:center}.icon-btn{width:36px;height:36px;border:none;border-radius:8px;color:white;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;text-decoration:none}.icon-btn .material-icons{font-size:19px}.btn-ok{background:#16a34a}.btn-hold{background:#f97316}.btn-resume{background:#0ea5e9}.btn-cancel{background:#dc2626}.btn-gis{background:#2563eb}.off{background:#9ca3af!important;cursor:not-allowed;opacity:.55;pointer-events:none}.footer-note{padding:10px 12px;font-size:12px;color:#6b7280;background:#f9fafb;border-top:1px solid #d1d5db;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.pagination{display:flex;align-items:center;justify-content:center;gap:8px;padding:10px 12px;border-top:1px solid #d1d5db;background:#fff}.page-btn{height:34px;min-width:34px;border:1px solid #cbd5e1;border-radius:7px;background:white;cursor:pointer;font-weight:800}.page-btn:disabled{opacity:.45;cursor:not-allowed}.page-info{font-size:13px;color:#475569;font-weight:700}@media(max-width:1000px){.toolbar{grid-template-columns:1fr 1fr}.verifier-table{min-width:1000px}}@media(max-width:700px){.page-header-card{flex-direction:column;align-items:flex-start}.toolbar{grid-template-columns:1fr}.verifier-content{overflow:visible}}
