<?php $n=1; if($result): while($r=$result->fetch_assoc()): $isPrio=$r['queue_type']==='priority'; $isHeld=$r['workflow_status']==='HELD'; $isCalled=$r['workflow_status']==='CALLED_STEP_2'; $isWaiting=$r['workflow_status']==='WAITING_STEP_2'; $counter=intval($r['counter_number'] ?: $r['table_number'] ?: 1); $gis=intval($r['form_locked']??0)===1 && ($r['eligibility_status']??'')==='Eligible' && floatval($r['approved_cash_amount']??0)>0; $statusClass=$isHeld?'status-held':($gis?'status-gis':($isCalled?'status-called':'status-waiting')); ?>
<tr class="data <?php echo $isHeld?'row-held':($isPrio?'row-priority':''); ?>" data-type="<?php echo h($r['queue_type']); ?>" data-status="<?php echo h($r['workflow_status']); ?>"><td class="row-number"><?php echo $n++; ?></td><td class="queue-number <?php echo $isPrio?'priority-queue-number':''; ?>"><?php echo h($r['queue_number']); ?><?php echo $isPrio?'<span class="priority-label">PRIO</span>':'<span class="regular-label">PAL</span>'; ?></td><td><span class="client-name"><?php echo h(fullName($r)); ?></span><span class="muted-small"><?php echo h($r['beneficiary_code'] ?? 'No code'); ?></span></td><td><?php echo h($r['barangay']); ?></td><td><?php echo intval($r['age']); ?></td><td><?php echo h($r['sex']); ?></td><td><?php echo h($r['lgu']); ?></td><td><span class="status-badge <?php echo $statusClass; ?>"><?php echo $gis?'GIS LOCKED':h($r['workflow_status']); ?></span><?php if($isCalled && $counter>0): ?><span class="counter-chip">Counter <?php echo $counter; ?></span><?php endif; ?></td><td><div class="action-group">
<?php if($isWaiting): ?>
<form method="POST" action="../api/call_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><?php echo counterDropdown(1); ?><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="icon-btn btn-ok" title="Call selected counter"><span class="material-icons">campaign</span></button></form>
<form method="POST" action="../api/hold_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="icon-btn btn-hold" title="Hold"><span class="material-icons">pause</span></button></form>
<form method="POST" action="../api/cancel_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="icon-btn btn-cancel" title="Cancel"><span class="material-icons">close</span></button></form>
<?php elseif($isCalled): ?>
<a class="icon-btn btn-gis" href="eligibility_form.php?queue_id=<?php echo intval($r['id']); ?>" title="GIS"><span class="material-icons">description</span></a>
<form method="POST" action="../api/mark_assessed.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="counter_number" value="<?php echo $counter ?: 1; ?>"><button class="icon-btn btn-ok <?php echo !$gis?'off':''; ?>" title="OK / Assessed"><span class="material-icons">check_circle</span></button></form>
<form method="POST" action="../api/hold_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="icon-btn btn-hold" title="Hold"><span class="material-icons">pause</span></button></form>
<form method="POST" action="../api/cancel_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="icon-btn btn-cancel" title="Cancel"><span class="material-icons">close</span></button></form>
<?php elseif($isHeld): ?>
<form method="POST" action="../api/resume_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="resume_to" value="WAITING_STEP_2"><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="icon-btn btn-resume" title="Resume Assessment"><span class="material-icons">play_arrow</span></button></form>
<form method="POST" action="../api/cancel_queue.php"><input type="hidden" name="queue_id" value="<?php echo intval($r['id']); ?>"><input type="hidden" name="redirect" value="../staff/assessment_screen.php"><button class="icon-btn btn-cancel" title="Cancel"><span class="material-icons">close</span></button></form>
