</tbody></table></div><div class="pagination" id="p"></div><div class="footer-note"><span id="recordInfo">Showing records...</span><span id="lastUpdated">Last updated: --</span></div></div>
</section></main><?php include('sidebar.php'); ?></div>
<script>
const rows=[...document.querySelectorAll('.data')],s=document.getElementById('s'),t=document.getElementById('t'),st=document.getElementById('st'),rpp=document.getElementById('rowsPerPage'),p=document.getElementById('p'),info=document.getElementById('recordInfo'),last=document.getElementById('lastUpdated');let page=1;function filteredRows(){let a=s.value.toLowerCase().trim(),ty=t.value,sta=st.value;return rows.filter(r=>(!ty||r.dataset.type===ty)&&(!sta||r.dataset.status===sta)&&r.innerText.toLowerCase().includes(a))}function apply(){let vis=filteredRows(),per=parseInt(rpp.value,10),pages=Math.max(1,Math.ceil(vis.length/per));if(page>pages)page=pages;rows.forEach(r=>r.style.display='none');vis.slice((page-1)*per,page*per).forEach(r=>r.style.display='');p.innerHTML=`<button class="page-btn" ${page===1?'disabled':''} onclick="page=1;apply()">«</button><button class="page-btn" ${page===1?'disabled':''} onclick="page--;apply()">‹</button><span class="page-info">Page ${page} of ${pages}</span><button class="page-btn" ${page===pages?'disabled':''} onclick="page++;apply()">›</button><button class="page-btn" ${page===pages?'disabled':''} onclick="page=${pages};apply()">»</button>`;let start=vis.length?(page-1)*per+1:0,end=Math.min(page*per,vis.length);info.textContent=`Showing ${start}-${end} of ${vis.length} filtered records (${rows.length} total)`;last.textContent='Last updated: '+new Date().toLocaleTimeString()}[s,t,st,rpp].forEach(e=>{e.addEventListener('input',()=>{page=1;apply()});e.addEventListener('change',()=>{page=1;apply()})});apply();
</script>
